import json,subprocess
b=Path('/workspace/2245-recommended-protections');i=json.loads((b/'canonical-invocation.json').read_text());c=i['container'];d=json.loads(subprocess.check_output(['docker','inspect',c],text=True))[0];state=d['State'];assert d['Id']==c and not state['Running'] and state['Pid']==0 and state['ExitCode']==0 and not state['OOMKilled'],'Not a completed passing container; preserve and inspect instead'
assert d['HostConfig']['Memory']==d['HostConfig']['MemorySwap']==2147483648 and d['HostConfig']['NanoCpus']==2000000000 and d['HostConfig']['NetworkMode']=='none' and d['Config']['User']=='1000:1000'
with (b/'local-container-stdout-original.log').open('wb') as f:subprocess.run(['docker','logs',c],stdout=f,stderr=subprocess.STDOUT,check=True)
with (b/'local-canonical-integrity-original.log').open('w') as f:subprocess.run(['python',str(b/'verify-local-canonical.py')],stdout=f,stderr=subprocess.STDOUT,check=True)
proof=json.loads((b/'local-verified.json').read_text());assert proof['all_local_gates_passed'] and proof['candidate']==i['candidate'] and proof['tree']==i['tree'];root=Path('/workspace/dtos-2245-local-completion');assert subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip()==i['candidate'] and subprocess.check_output(['git','rev-parse','HEAD^{tree}'],cwd=root,text=True).strip()==i['tree'] and not subprocess.check_output(['git','status','--porcelain'],cwd=root,text=True).strip()
subprocess.run(['docker','rm',c],check=True,stdout=subprocess.DEVNULL);assert not subprocess.check_output(['docker','ps','-a','--filter','id='+c,'--format','{{.ID}}'],text=True).strip()
r=dict(observed_at=datetime.now(timezone.utc).isoformat(),candidate=i['candidate'],tree=i['tree'],container=c,started_at=state['StartedAt'],finished_at=state['FinishedAt'],exit_code=state['ExitCode'],oom_killed=state['OOMKilled'],pid_after=state['Pid'],stopped_container_removed=True,container_absent_after_removal=True,all_original_manifest_bytes_verified=True,all_local_tests_and_ten_gates_passed=True,working_tree_clean=True,scope='Original Docker stdout collected after real exit0; source/limits/counters/all10gates/manifest verified before ordinary removal of this stopped validation container. Container PID0 proves no processes remain there; per-worker cancellation/timeout cleanup is separately established by native controls, not inferred from container teardown. No long-term leak claim.')
(b/'local-container-cleanup.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r))
